const { TestEnvironment } = require('jest-environment-node')
const fs = require('node:fs')
const path = require('node:path')

const SYNC = new Set([
  'start_describe_definition',
  'finish_describe_definition',
  'add_hook',
  'add_test',
  'error',
  'error_handled',
])
const firstLine = (value) =>
  String(value && value.message !== undefined ? value.message : value).split('\n')[0]
const nameOf = (block) => (block ? block.name : null)
const NAMED = ['blockName', 'testName', 'hookType', 'mode', 'concurrent', 'failing', 'timeout']

function summarize(event, state) {
  const out = { name: event.name }
  for (const key of NAMED) if (event[key] !== undefined) out[key] = event[key]
  if (event.fn !== undefined) out.hasFn = typeof event.fn === 'function'
  if (event.asyncError !== undefined) out.hasAsyncError = event.asyncError !== undefined
  if (event.testNamePattern !== undefined) out.testNamePattern = event.testNamePattern
  if (event.parentProcess !== undefined) out.parentProcessIsProcess = event.parentProcess === process
  if (event.runtimeGlobals !== undefined) out.runtimeGlobals = typeof event.runtimeGlobals
  if (event.error !== undefined) out.error = firstLine(event.error)
  const test = event.test
  if (test) {
    out.test = {
      name: test.name,
      parent: nameOf(test.parent),
      mode: test.mode,
      status: test.status,
      invocations: test.invocations,
      errors: test.errors.length,
      retryReasons: test.retryReasons.length,
      concurrent: test.concurrent,
      failing: test.failing,
      startedAt: typeof test.startedAt,
      duration: typeof test.duration,
    }
  }
  const block = event.describeBlock
  if (block) {
    out.describeBlock = {
      name: block.name,
      parent: nameOf(block.parent),
      mode: block.mode,
      children: block.children.length,
      hooks: block.hooks.length,
    }
  }
  if (event.hook) out.hook = { type: event.hook.type, parent: nameOf(event.hook.parent) }
  if (event.tests) out.tests = event.tests.map((entry) => entry.name)
  out.state = {
    currentDescribeBlock: nameOf(state.currentDescribeBlock),
    currentlyRunningTest: state.currentlyRunningTest ? state.currentlyRunningTest.name : null,
    hasFocusedTests: state.hasFocusedTests,
    hasStarted: state.hasStarted,
    includeTestLocationInResult: state.includeTestLocationInResult,
    unhandledErrors: state.unhandledErrors.length,
    rootChildren: state.rootDescribeBlock.children.length,
    testNamePattern: state.testNamePattern ? String(state.testNamePattern) : null,
    testTimeout: state.testTimeout,
    maxConcurrency: state.maxConcurrency,
    randomize: state.randomize === true,
    expand: state.expand === true,
  }
  return out
}

class RecordingEnvironment extends TestEnvironment {
  constructor(config, context) {
    super(config, context)
    this.eventsFile = path.join(config.projectConfig.rootDir, 'events.jsonl')
    this.global.__log = (marker) => this.record({ marker })
  }

  record(entry) {
    fs.appendFileSync(this.eventsFile, JSON.stringify(entry) + '\n')
  }

  handleTestEvent(event, state) {
    this.record(summarize(event, state))
  }
}

module.exports = RecordingEnvironment
